+                    // TODO skip in query?
+                    continue;
+                }
+                long time = Long.parseLong((String) hit.getSortValues()[dimensionFieldNames.size()]);
+                double value = ((Number) metricField.getValue()).doubleValue();
+                callback.onMetric(time, value);
+            }
