+        return IndexRouting.fromIndexMetadata(
+            IndexMetadata.builder("test")
+                .settings(settings(createdVersion).put(IndexMetadata.INDEX_ROUTING_PATH.getKey(), path))
+                .numberOfShards(shards)
+                .numberOfReplicas(1)
+                .build()
